def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Split at the uniform separator; the pattern to encode is the panel
    # before the separator.
    for r in range(h):
        if len(set(grid[r])) == 1:
            pattern = grid[:r]
            other = grid[r + 1:]
            break
    else:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)):
                pattern = [row[:c] for row in grid]
                other = [row[c + 1:] for row in grid]
                break
        else:
            pattern, other = grid, []

    pc = Counter(x for row in pattern for x in row)
    oc = Counter(x for row in other for x in row)
    background = pc.most_common(1)[0][0]

    # Use the other panel's dominant color when it is also one of the
    # pattern's colors; otherwise retain the pattern's dominant color.
    if oc:
        candidate = oc.most_common(1)[0][0]
        if candidate in pc:
            background = candidate

    return [[background if x == pc.most_common(1)[0][0] else 3
             for x in row] for row in pattern]
